CREATE OR REPLACE FUNCTION public.refund_credit(p_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN UPDATE public.user_credits SET credits_remaining = credits_remaining + 1, credits_used = greatest(credits_used - 1, 0), updated_at = now() WHERE user_id = p_user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Credit account not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.refund_credit(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.refund_credit(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.refund_agent_guest_credit(p_key_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE k public.agent_guest_keys%ROWTYPE; BEGIN SELECT * INTO k FROM public.agent_guest_keys WHERE id = p_key_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Key not found'; END IF; IF k.claimed_by IS NOT NULL THEN UPDATE public.user_credits SET credits_remaining = credits_remaining + 1, updated_at = now() WHERE user_id = k.claimed_by; ELSE UPDATE public.agent_guest_keys SET credits_remaining = credits_remaining + 1 WHERE id = k.id; END IF; END $$;
REVOKE ALL ON FUNCTION public.refund_agent_guest_credit(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.refund_agent_guest_credit(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_agent_key(p_key_hash text, p_user_id uuid) RETURNS TABLE(panels_moved integer, credits_added integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE k public.agent_guest_keys%ROWTYPE; moved integer; BEGIN SELECT * INTO k FROM public.agent_guest_keys WHERE key_hash = p_key_hash FOR UPDATE; IF NOT FOUND OR k.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Invalid or revoked link'; END IF; IF k.claimed_by IS NOT NULL THEN IF k.claimed_by <> p_user_id THEN RAISE EXCEPTION 'Link already belongs to another account'; END IF; RETURN QUERY SELECT 0, 0; RETURN; END IF; UPDATE public.user_credits SET credits_remaining = credits_remaining + k.credits_remaining, updated_at = now() WHERE user_id = p_user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Credit account not found'; END IF; UPDATE public.agent_chats SET user_id = p_user_id WHERE guest_key_id = k.id AND user_id IS NULL; GET DIAGNOSTICS moved = ROW_COUNT; UPDATE public.agent_guest_keys SET claimed_by = p_user_id, claimed_at = now(), credits_remaining = 0 WHERE id = k.id; RETURN QUERY SELECT moved, k.credits_remaining; END $$;
REVOKE ALL ON FUNCTION public.claim_agent_key(text, uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.claim_agent_key(text, uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.use_guest_key_credit(p_key_hash text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_remaining integer; BEGIN UPDATE public.agent_guest_keys SET credits_remaining = credits_remaining - 1, last_used_at = now() WHERE key_hash = p_key_hash AND revoked_at IS NULL AND claimed_by IS NULL AND credits_remaining > 0 RETURNING credits_remaining INTO v_remaining; RETURN coalesce(v_remaining, -1); END $$; REVOKE ALL ON FUNCTION public.use_guest_key_credit(text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.use_guest_key_credit(text) TO service_role;